# Pulumi ComponentResource: Application Infrastructure (TypeScript)

This implementation wraps S3, RDS PostgreSQL, and IAM role into a reusable ComponentResource, with environment-specific configuration via stack files.

## Component Class

**`component.ts`**

```typescript
import * as aws from "@pulumi/aws";
import * as pulumi from "@pulumi/pulumi";

export interface ApplicationComponentArgs {
  environment: "dev" | "prod";
  bucketName: string;
  dbInstanceClass: string;
  dbMultiAz: boolean;
  iamRoleName: string;
  vpcId: string;
  dbSubnetGroupName?: string;
  enableCrossRegionReplication?: boolean;
  replicationRegion?: string;
  dbBackupRetentionDays?: number;
  oidcProviderArn?: string; // For prod OIDC trust
}

export class ApplicationComponentResource extends pulumi.ComponentResource {
  public readonly bucketName: pulumi.Output<string>;
  public readonly bucketArn: pulumi.Output<string>;
  public readonly dbEndpoint: pulumi.Output<string>;
  public readonly dbName: pulumi.Output<string>;
  public readonly dbIdentifier: pulumi.Output<string>;
  public readonly iamRoleArn: pulumi.Output<string>;
  public readonly iamRoleName: pulumi.Output<string>;
  public readonly securityGroupId: pulumi.Output<string>;

  constructor(
    name: string,
    args: ApplicationComponentArgs,
    opts?: pulumi.ComponentResourceOptions
  ) {
    super("app:infrastructure:ApplicationComponent", name, {}, opts);

    const parentOpts = { parent: this };
    const env = args.environment;

    // ==================== S3 Bucket ====================
    const bucket = new aws.s3.Bucket(
      `${name}-bucket`,
      {
        bucket: args.bucketName,
        forceDestroy: false, // Prevent accidental deletion
      },
      parentOpts
    );

    // Enable versioning
    new aws.s3.BucketVersioningV2(
      `${name}-versioning`,
      {
        bucket: bucket.id,
        versioningConfiguration: {
          status: "Enabled",
        },
      },
      parentOpts
    );

    // Server-side encryption (AES-256)
    new aws.s3.BucketServerSideEncryptionConfigurationV2(
      `${name}-encryption`,
      {
        bucket: bucket.id,
        rules: [
          {
            applyServerSideEncryptionByDefault: {
              sseAlgorithm: "AES256",
            },
          },
        ],
      },
      parentOpts
    );

    // Block all public access (critical for security)
    new aws.s3.BucketPublicAccessBlock(
      `${name}-public-access-block`,
      {
        bucket: bucket.id,
        blockPublicAcls: true,
        blockPublicPolicy: true,
        ignorePublicAcls: true,
        restrictPublicBuckets: true,
      },
      parentOpts
    );

    // Prod: Cross-region replication to us-west-2
    if (env === "prod" && args.enableCrossRegionReplication) {
      this._setupCrossRegionReplication(
        name,
        bucket,
        args.replicationRegion || "us-west-2",
        parentOpts
      );
    }

    // ==================== RDS PostgreSQL ====================

    // Security group: restrict inbound to VPC
    const dbSecurityGroup = new aws.ec2.SecurityGroup(
      `${name}-db-sg`,
      {
        vpcId: args.vpcId,
        ingress: [
          {
            fromPort: 5432,
            toPort: 5432,
            protocol: "tcp",
            cidrBlocks: ["10.0.0.0/8"], // Adjust to your VPC CIDR
            description: "PostgreSQL from app VPC",
          },
        ],
        egress: [
          {
            fromPort: 0,
            toPort: 0,
            protocol: "-1",
            cidrBlocks: ["0.0.0.0/0"],
            description: "Allow all outbound",
          },
        ],
      },
      parentOpts
    );

    // DB subnet group (multi-AZ requires at least 2 subnets)
    const dbSubnetGroup = new aws.rds.SubnetGroup(
      `${name}-db-subnet-group`,
      {
        subnetIds: this._getDbSubnetIds(args.vpcId),
        tags: { Name: `${name}-db-subnet-group` },
      },
      parentOpts
    );

    // Database password from stack secret
    const dbPassword = pulumi
      .Config()
      .requireSecret("dbPassword")
      .then((p) => p);

    const dbInstance = new aws.rds.Instance(
      `${name}-db`,
      {
        allocatedStorage: 20,
        storageType: "gp3",
        engine: "postgres",
        engineVersion: "15.5",
        instanceClass: args.dbInstanceClass,
        dbName: "appdb",
        username: "postgres",
        password: dbPassword,
        dbSubnetGroupName: dbSubnetGroup.name,
        vpcSecurityGroupIds: [dbSecurityGroup.id],

        // Deletion protection and backup
        deletionProtection: true,
        skipFinalSnapshot: false,
        finalSnapshotIdentifierPrefix: `${name}-final-snapshot`,
        backupRetentionPeriod: args.dbBackupRetentionDays || 7,

        // HA for prod
        multiAz: args.dbMultiAz,
        storageEncrypted: args.dbMultiAz, // Encrypt when multi-AZ (prod)

        // Network isolation
        publiclyAccessible: false,

        // Logging
        enableCloudwatchLogsExports: ["postgresql"],

        // Performance insights (optional, useful for prod)
        performanceInsightsEnabled: env === "prod",
        performanceInsightsRetentionPeriod:
          env === "prod" ? 7 : undefined,

        tags: {
          Environment: env,
          ManagedBy: "Pulumi",
        },
      },
      { parent: this, dependsOn: [dbSubnetGroup] }
    );

    // ==================== IAM Role ====================

    let assumeRolePolicy: pulumi.Output<string>;

    if (env === "prod" && args.oidcProviderArn) {
      // Prod: OIDC trust for Kubernetes
      assumeRolePolicy = aws.iam.getPolicyDocumentOutput({
        statements: [
          {
            principals: [
              {
                type: "Federated",
                identifiers: [args.oidcProviderArn],
              },
            ],
            actions: ["sts:AssumeRoleWithWebIdentity"],
            effect: "Allow",
            conditions: [
              {
                test: "StringEquals",
                variable:
                  "oidc.eks.${REGION}.amazonaws.com/id/${OIDC_ID}:sub",
                values: ["system:serviceaccount:default:app-service"],
              },
            ],
          },
        ],
      }).json;
    } else {
      // Dev: EC2 instance principal trust
      assumeRolePolicy = aws.iam.getPolicyDocumentOutput({
        statements: [
          {
            principals: [
              {
                type: "Service",
                identifiers: ["ec2.amazonaws.com"],
              },
            ],
            actions: ["sts:AssumeRole"],
            effect: "Allow",
          },
        ],
      }).json;
    }

    const iamRole = new aws.iam.Role(
      `${name}-service-role`,
      {
        name: args.iamRoleName,
        assumeRolePolicy: assumeRolePolicy,
        tags: {
          Environment: env,
          ManagedBy: "Pulumi",
        },
      },
      parentOpts
    );

    // Least-privilege inline policy
    new aws.iam.RolePolicy(
      `${name}-service-policy`,
      {
        role: iamRole.id,
        policy: aws.iam.getPolicyDocumentOutput({
          statements: [
            // S3 access
            {
              effect: "Allow",
              actions: ["s3:ListBucket", "s3:GetBucketVersioning"],
              resources: [bucket.arn],
              conditions:
                env === "prod"
                  ? [
                      {
                        test: "StringEquals",
                        variable: "s3:x-amz-server-side-encryption",
                        values: ["AES256"],
                      },
                    ]
                  : undefined,
            },
            {
              effect: "Allow",
              actions: ["s3:GetObject", "s3:PutObject"],
              resources: [pulumi.interpolate`${bucket.arn}/*`],
              conditions:
                env === "prod"
                  ? [
                      {
                        test: "StringEquals",
                        variable: "s3:x-amz-server-side-encryption",
                        values: ["AES256"],
                      },
                    ]
                  : undefined,
            },
            // RDS database authentication
            {
              effect: "Allow",
              actions: ["rds-db:connect"],
              resources: [
                pulumi.interpolate`arn:aws:rds:${"*"}:${"*"}:db/${dbInstance.identifier}`,
              ],
            },
            // Secrets access (for DB connection string)
            {
              effect: "Allow",
              actions: ["secretsmanager:GetSecretValue"],
              resources: [
                pulumi.interpolate`arn:aws:secretsmanager:${"*"}:${"*"}:secret:${name}/db-*`,
              ],
            },
          ],
        }).json,
      },
      parentOpts
    );

    // ==================== Outputs ====================
    this.bucketName = bucket.id;
    this.bucketArn = bucket.arn;
    this.dbEndpoint = dbInstance.endpoint;
    this.dbName = dbInstance.dbName;
    this.dbIdentifier = dbInstance.identifier;
    this.iamRoleArn = iamRole.arn;
    this.iamRoleName = iamRole.name;
    this.securityGroupId = dbSecurityGroup.id;

    this.registerOutputs({
      bucketName: this.bucketName,
      bucketArn: this.bucketArn,
      dbEndpoint: this.dbEndpoint,
      dbName: this.dbName,
      dbIdentifier: this.dbIdentifier,
      iamRoleArn: this.iamRoleArn,
      iamRoleName: this.iamRoleName,
      securityGroupId: this.securityGroupId,
    });
  }

  /**
   * Setup cross-region replication (prod only).
   */
  private _setupCrossRegionReplication(
    name: string,
    sourceBucket: aws.s3.Bucket,
    replicationRegion: string,
    parentOpts: pulumi.ComponentResourceOptions
  ): void {
    // Replication role with S3 permissions
    const replicationRole = new aws.iam.Role(
      `${name}-replication-role`,
      {
        assumeRolePolicy: aws.iam.getPolicyDocumentOutput({
          statements: [
            {
              principals: [
                {
                  type: "Service",
                  identifiers: ["s3.amazonaws.com"],
                },
              ],
              actions: ["sts:AssumeRole"],
              effect: "Allow",
            },
          ],
        }).json,
      },
      parentOpts
    );

    new aws.iam.RolePolicy(
      `${name}-replication-policy`,
      {
        role: replicationRole.id,
        policy: aws.iam.getPolicyDocumentOutput({
          statements: [
            {
              effect: "Allow",
              actions: ["s3:GetReplicationConfiguration", "s3:ListBucket"],
              resources: [sourceBucket.arn],
            },
            {
              effect: "Allow",
              actions: [
                "s3:GetObjectVersionForReplication",
                "s3:GetObjectVersionAcl",
              ],
              resources: [pulumi.interpolate`${sourceBucket.arn}/*`],
            },
            {
              effect: "Allow",
              actions: ["s3:ReplicateObject", "s3:ReplicateDelete"],
              resources: [
                pulumi.interpolate`arn:aws:s3:::${sourceBucket.id}-replica/*`,
              ],
            },
          ],
        }).json,
      },
      parentOpts
    );

    // Create replica bucket in secondary region
    const replicaBucket = new aws.s3.Bucket(
      `${name}-replica-bucket`,
      {
        bucket: pulumi.interpolate`${sourceBucket.id}-replica`,
      },
      { ...parentOpts, provider: new aws.Provider(`${name}-replica-provider`, { region: replicationRegion }) }
    );

    // Enable versioning on replica
    new aws.s3.BucketVersioningV2(
      `${name}-replica-versioning`,
      {
        bucket: replicaBucket.id,
        versioningConfiguration: { status: "Enabled" },
      },
      parentOpts
    );

    // Configure replication rule
    new aws.s3.BucketReplicationConfig(
      `${name}-replication-config`,
      {
        role: replicationRole.arn,
        bucket: sourceBucket.id,
        rules: [
          {
            status: "Enabled",
            priority: 1,
            filter: { prefix: "" },
            destination: {
              bucket: replicaBucket.arn,
              replicationTime: {
                status: "Enabled",
                time: { minutes: 15 },
              },
              metrics: {
                status: "Enabled",
                eventThreshold: { minutes: 15 },
              },
            },
            deleteMarkerReplication: {
              status: "Enabled",
            },
          },
        ],
      },
      parentOpts
    );
  }

  /**
   * Fetch subnets for DB subnet group (multi-AZ).
   */
  private _getDbSubnetIds(vpcId: string): pulumi.Output<string[]> {
    return aws.ec2
      .getSubnets({
        filters: [
          {
            name: "vpc-id",
            values: [vpcId],
          },
        ],
      })
      .then((result) => result.ids.slice(0, 2)); // At least 2 for RDS multi-AZ
  }
}
```

## Stack Consumer

**`index.ts`**

```typescript
import * as pulumi from "@pulumi/pulumi";
import { ApplicationComponentResource } from "./component";

const config = new pulumi.Config();
const stack = pulumi.getStack();

// Read config (dev.yaml / prod.yaml)
const bucketName = config.require("bucketName");
const dbInstanceClass = config.require("dbInstanceClass");
const dbMultiAz = config.requireBoolean("dbMultiAz");
const vpcId = config.require("vpcId");
const oidcProviderArn = config.get("oidcProviderArn");
const enableReplication = config.getBoolean("enableReplication") ?? false;

// Instantiate component
const appInfra = new ApplicationComponentResource(
  "app",
  {
    environment: stack as "dev" | "prod",
    bucketName,
    dbInstanceClass,
    dbMultiAz,
    vpcId,
    iamRoleName: `${stack}-app-service-role`,
    enableCrossRegionReplication: enableReplication,
    replicationRegion: config.get("replicationRegion") ?? "us-west-2",
    dbBackupRetentionDays: config.getNumber("dbBackupRetentionDays") ?? 7,
    oidcProviderArn,
  }
);

// Export for downstream consumption
export const bucketName = appInfra.bucketName;
export const bucketArn = appInfra.bucketArn;
export const dbEndpoint = appInfra.dbEndpoint;
export const dbIdentifier = appInfra.dbIdentifier;
export const iamRoleArn = appInfra.iamRoleArn;
export const iamRoleName = appInfra.iamRoleName;
export const securityGroupId = appInfra.securityGroupId;
```

## Stack Configuration

**`dev.yaml`**

```yaml
bucketName: "my-app-assets-dev-${USER}"
dbInstanceClass: "db.t3.micro"
dbMultiAz: false
vpcId: "vpc-dev12345"
dbPassword:
  secure: AAABAxxxx+xxxxxxxxxxxxx=  # pulumi config set --secret dbPassword <password>
enableReplication: false
dbBackupRetentionDays: 7
```

**`prod.yaml`**

```yaml
bucketName: "my-app-assets-prod"
dbInstanceClass: "db.t3.medium"
dbMultiAz: true
vpcId: "vpc-prod67890"
dbPassword:
  secure: AAABAxxxx+xxxxxxxxxxxxx=  # pulumi config set --secret dbPassword <password>
enableReplication: true
replicationRegion: "us-west-2"
dbBackupRetentionDays: 30
oidcProviderArn: "arn:aws:iam::123456789012:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLEID"
```

## Usage

```bash
# Set secrets (before deployment)
pulumi config set --secret dbPassword "your-secure-password"

# Deploy dev
pulumi stack select dev
pulumi up

# Deploy prod
pulumi stack select prod
pulumi up

# Query outputs
pulumi stack output bucketName
pulumi stack output iamRoleArn
```

## Key Features

✅ **Single component** wraps bucket, RDS, and IAM  
✅ **Versioning & encryption** on S3 (no public access)  
✅ **Deletion protection** and 7-day backup retention on RDS  
✅ **Prod features**: Multi-AZ, cross-region replication, OIDC trust  
✅ **Least-privilege IAM**: Conditional policies, no wildcards on prod  
✅ **Stack config isolation**: dev and prod independently deployable  
✅ **Secrets handling**: `dbPassword` via `pulumi config set --secret`  
✅ **Type-safe**: Full TypeScript interfaces for args and outputs
